server_scripts.script:
# GitHub Tool: read_pull_request (flat, no def). Read-only.
# One call returns what a fix needs: the pull request's description, its files
# with a short diff, and every review comment — the ones asking for changes first.
import re

from frappe.integrations.utils import make_get_request

_url = (task_data.get("pr_url") or "").strip()
if not _url and context_doctype == "A2A Task" and context_docname:
    _payload = frappe.parse_json(frappe.db.get_value("A2A Task", context_docname, "request_payload") or "{}") or {}
    _url = (_payload.get("pull_request") or "").strip()
if not _url and context_doctype == "Work Item" and context_docname:
    _url = (frappe.db.get_value("Work Item", context_docname, "pr_link") or "").strip()

_m = re.match(r"https?://github\.com/([^/\s]+)/([^/\s]+)/pull/(\d+)", _url)
if not _url:
    result["error"] = "No pull request to read: pass pr_url, or run on a Work Item or delegation that has one."
elif not _m:
    result["error"] = _url + " is not a GitHub pull request URL (expected https://github.com/<owner>/<repo>/pull/<number>)."
else:
    _owner, _repo, _num = _m.group(1), _m.group(2), _m.group(3)
    _token = frappe.get_cached_doc("Processa Settings").get_password("github_token", raise_exception=False) or ""
    _headers = {"Accept": "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28"}
    if _token:
        _headers["Authorization"] = "Bearer " + _token
    _base = "https://api.github.com/repos/" + _owner + "/" + _repo
    try:
        _pr = make_get_request(_base + "/pulls/" + _num, headers=_headers)
        _files = make_get_request(_base + "/pulls/" + _num + "/files?per_page=100", headers=_headers) or []
        _reviews = make_get_request(_base + "/pulls/" + _num + "/reviews?per_page=100", headers=_headers) or []
        _inline = make_get_request(_base + "/pulls/" + _num + "/comments?per_page=100", headers=_headers) or []
        _thread = make_get_request(_base + "/issues/" + _num + "/comments?per_page=100", headers=_headers) or []
    except Exception as _exc:
        result["error"] = "GitHub did not answer for " + _url + ": " + str(_exc)[:300]
    else:
        result["url"] = _url
        result["number"] = int(_num)
        result["title"] = _pr.get("title")
        result["description"] = (_pr.get("body") or "")[:4000]
        result["state"] = "merged" if _pr.get("merged") else _pr.get("state")
        result["head_branch"] = (_pr.get("head") or {}).get("ref")
        result["base_branch"] = (_pr.get("base") or {}).get("ref")
        result["author"] = (_pr.get("user") or {}).get("login")
        result["files"] = [
            {"path": _f.get("filename"), "status": _f.get("status"), "additions": _f.get("additions"),
             "deletions": _f.get("deletions"), "diff": (_f.get("patch") or "")[:1500]}
            for _f in _files[:40]
        ]
        result["reviews"] = [
            {"reviewer": (_r.get("user") or {}).get("login"), "state": _r.get("state"), "body": (_r.get("body") or "").strip()[:1500]}
            for _r in _reviews if _r.get("state") != "PENDING" and (_r.get("state") != "COMMENTED" or (_r.get("body") or "").strip())
        ]
        result["review_comments"] = [
            {"path": _c.get("path"), "line": _c.get("line") or _c.get("original_line"),
             "reviewer": (_c.get("user") or {}).get("login"), "body": (_c.get("body") or "").strip()[:1500]}
            for _c in _inline[:60]
        ]
        result["comments"] = [
            {"author": (_c.get("user") or {}).get("login"), "body": (_c.get("body") or "").strip()[:1500]}
            for _c in _thread[:30]
        ]
        result["changes_requested"] = [_r for _r in result["reviews"] if _r["state"] == "CHANGES_REQUESTED"]
        result["summary"] = (
            str(len(result["files"])) + " file(s) changed; " + str(len(result["changes_requested"]))
            + " review(s) asked for changes; " + str(len(result["review_comments"])) + " inline comment(s)."
        )
